define(["jquery"],function($){"use strict";function init(ctx,cfg){if(!cfg){return}let cmid=Number(ctx.cmid||0);let attemptid=Number(ctx.attemptid||0);let $container=$('[data-kppass="container"]');if($container.length===0){return}let $footer=$container.find(".kopere-proctoring-footer");let $status=$container.find('[data-kppass="status"]');let $inputPassword=$container.find('[data-kppass="password"]');let $btnSubmit=$container.find('[data-kppass="submit"]');let polling=null;if(ctx.api&&typeof ctx.api.registerRequirement==="function"){ctx.api.registerRequirement("password",{label:M.util.get_string("requirement_label","proctoringpolicy_password"),satisfied:false})}setPendingState(false);function setPendingState(satisfied){if(typeof updatePendingState==="function"){updatePendingState($footer,$inputPassword,$(),!!satisfied);return}if($footer.length){$footer.toggleClass("is-pending",!satisfied)}if($inputPassword.length){$inputPassword.attr("aria-invalid",satisfied?"false":"true")}}function setRequirementSatisfied(satisfied){if(ctx.api&&typeof ctx.api.updateRequirement==="function"){ctx.api.updateRequirement("password",{satisfied:!!satisfied})}setPendingState(!!satisfied)}function setStatus(kind,text){if(!text){$status.empty().hide();return}let classname="alert-info";if(kind==="success"){classname="alert-success"}else if(kind==="warning"){classname="alert-warning"}else if(kind==="danger"){classname="alert-danger"}$status.html('<div class="alert '+classname+' mb-2">'+text+"</div>").show()}function stopPolling(){if(polling){window.clearInterval(polling);polling=null}}function handleStatusResponse(resp){if(!resp){setRequirementSatisfied(false);setStatus("warning",M.util.get_string("js_status_pending","proctoringpolicy_password"));return}if(resp.error==="blocked"||resp.status==="blocked"){setRequirementSatisfied(false);setStatus("danger",M.util.get_string("js_status_blocked","proctoringpolicy_password"));stopPolling();return}if(resp.status==="approved"){setRequirementSatisfied(true);setStatus("success",M.util.get_string("js_status_approved","proctoringpolicy_password"));$inputPassword.prop("disabled",true);$("#password-student_enter_password").hide(300);$("#password-student_footer").hide(300);$btnSubmit.prop("disabled",true);window.dispatchEvent(new CustomEvent("kopere_proctoring_password_authorized",{detail:{cmid:cmid,attemptid:attemptid}}));stopPolling();return}setRequirementSatisfied(false);setStatus("warning",M.util.get_string("js_status_pending","proctoringpolicy_password"))}function checkStatus(){console.log("checkStatus");return;$.ajax({url:`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/ajax.php`,method:"POST",dataType:"json",data:{action:"check",cmid:cmid,attemptid:attemptid}}).done(function(response){handleStatusResponse(response)}).fail(function(){setRequirementSatisfied(false)})}function startPolling(){if(polling){return}checkStatus();polling=window.setInterval(checkStatus,3e3)}function ensureRequestExists(){$.ajax({url:`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/ajax.php`,method:"POST",dataType:"json",data:{action:"request",cmid:cmid,attemptid:attemptid,browserinfo:window.navigator.userAgent||""}}).done(function(response){handleStatusResponse(response)}).always(function(){startPolling()})}ensureRequestExists();$btnSubmit.on("click",function(){let code=($inputPassword.val()||"").trim();if(code.length!==6){setRequirementSatisfied(false);setStatus("danger",M.util.get_string("student_wrong_password","proctoringpolicy_password"));console.log("OPs....");return}$.ajax({url:`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/ajax.php`,method:"POST",dataType:"json",data:{action:"submitcode",cmid:cmid,attemptid:attemptid,code:code}}).done(function(resp){if(!resp){return}if(resp.error==="blocked"){setRequirementSatisfied(false);setStatus("danger",M.util.get_string("js_toomany_errors","proctoringpolicy_password"));stopPolling();return}if(resp.error==="wrong"){setRequirementSatisfied(false);setStatus("danger",M.util.get_string("student_wrong_password","proctoringpolicy_password"));return}if(resp.status==="approved"){handleStatusResponse(resp)}})})}return{init:init}});